// Only this exact pure validator may prune its broader identity-package import.
// Direct identity imports and any byte/import drift remain ordinary dependencies.
func ingressPilotDependencyPruning(packages []listedPackage, module string) map[string]bool {
	pruned := map[string]bool{}
	for _, candidate := range packages {
		if candidate.ImportPath == module+"/internal/networkingress" && approvedNetworkConnectPackage(checkedSourcePackage{listed: candidate}, module, "internal/networkingress") {
			pruned[candidate.ImportPath] = true
		}
	}
	return pruned
}
